 *
 * The supported methods are the limited to what's supported by android-components.
 */

enum class Method(val value: kotlin.UByte) {
    
    GET(0u),
    HEAD(1u),
    POST(2u),
    PUT(3u),
    DELETE(4u),
    CONNECT(5u),
    OPTIONS(6u),
    TRACE(7u),
    PATCH(8u);

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeMethod: FfiConverterRustBuffer<Method> {
    override fun read(buf: ByteBuffer) = try {
        Method.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: Method) = 4UL

    override fun write(value: Method, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







sealed class ViaductException: kotlin.Exception() {
    
    class RequestHeaderException(
        
        val v1: kotlin.String
        ) : ViaductException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class BackendException(
        
        val v1: kotlin.String
        ) : ViaductException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class NetworkException(
        
        val v1: kotlin.String
        ) : ViaductException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class BackendAlreadyInitialized(
        ) : ViaductException() {
        override val message
            get() = ""
    }
    
    class BackendNotInitialized(
        ) : ViaductException() {
        override val message
            get() = ""
    }
    
    class SetBackendException(
        ) : ViaductException() {
        override val message
            get() = ""
    }
    
    /**
     * Note: we return this if the server returns a bad URL with
     * its response. This *probably* should never happen, but who knows.
     */
    class UrlException(
        
        val v1: kotlin.String
        ) : ViaductException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class NonTlsUrl(
        ) : ViaductException() {
        override val message
            get() = ""
    }
    
    class OhttpChannelNotConfigured(
        
        val v1: kotlin.String
        ) : ViaductException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class OhttpConfigFetchFailed(
        
        val v1: kotlin.String
        ) : ViaductException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class OhttpRequestException(
        
        val v1: kotlin.String
        ) : ViaductException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class OhttpResponseException(
        
        val v1: kotlin.String
        ) : ViaductException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class OhttpNotSupported(
        ) : ViaductException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ViaductException> {
        override fun lift(error_buf: RustBuffer.ByValue): ViaductException = FfiConverterTypeViaductError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeViaductError : FfiConverterRustBuffer<ViaductException> {
    override fun read(buf: ByteBuffer): ViaductException {
        

        return when(buf.getInt()) {
            1 -> ViaductException.RequestHeaderException(
                FfiConverterString.read(buf),
                )
            2 -> ViaductException.BackendException(
                FfiConverterString.read(buf),
                )
            3 -> ViaductException.NetworkException(
                FfiConverterString.read(buf),
                )
            4 -> ViaductException.BackendAlreadyInitialized()
            5 -> ViaductException.BackendNotInitialized()
            6 -> ViaductException.SetBackendException()
            7 -> ViaductException.UrlException(
                FfiConverterString.read(buf),
                )
            8 -> ViaductException.NonTlsUrl()
            9 -> ViaductException.OhttpChannelNotConfigured(
                FfiConverterString.read(buf),
                )
            10 -> ViaductException.OhttpConfigFetchFailed(
                FfiConverterString.read(buf),
                )
            11 -> ViaductException.OhttpRequestException(
                FfiConverterString.read(buf),
                )
            12 -> ViaductException.OhttpResponseException(
                FfiConverterString.read(buf),
                )
            13 -> ViaductException.OhttpNotSupported()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ViaductException): ULong {
        return when(value) {
