                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ViaductException.SetBackendException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ViaductException.UrlException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ViaductException.NonTlsUrl -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ViaductException.OhttpChannelNotConfigured -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ViaductException.OhttpConfigFetchFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ViaductException.OhttpRequestException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ViaductException.OhttpResponseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is ViaductException.OhttpNotSupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: ViaductException, buf: ByteBuffer) {
        when(value) {
            is ViaductException.RequestHeaderException -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ViaductException.BackendException -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ViaductException.NetworkException -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ViaductException.BackendAlreadyInitialized -> {
                buf.putInt(4)
                Unit
            }
            is ViaductException.BackendNotInitialized -> {
                buf.putInt(5)
                Unit
            }
            is ViaductException.SetBackendException -> {
                buf.putInt(6)
                Unit
            }
            is ViaductException.UrlException -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ViaductException.NonTlsUrl -> {
                buf.putInt(8)
                Unit
            }
            is ViaductException.OhttpChannelNotConfigured -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ViaductException.OhttpConfigFetchFailed -> {
                buf.putInt(10)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ViaductException.OhttpRequestException -> {
                buf.putInt(11)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ViaductException.OhttpResponseException -> {
                buf.putInt(12)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is ViaductException.OhttpNotSupported -> {
                buf.putInt(13)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




